 40| // ===== Window Control Commands =====
 41| 
 42| #[tauri::command]
 43| async fn minimize(window: tauri::Window) -> Result<(), String> {
 44|     window.minimize().map_err(|e| e.to_string())
 45| }
 46| 
 47| #[tauri::command]
 48| async fn toggle_maximize(window: tauri::Window) -> Result<(), String> {
 49|     if window.is_maximized().map_err(|e| e.to_string())? {
 50|         window.unmaximize().map_err(|e| e.to_string())?;
 51|     } else {
 52|         window.maximize().map_err(|e| e.to_string())?;
 53|     }
 54|     Ok(())
 55| }
 56| 
 57| #[tauri::command]
 58| async fn close(window: tauri::Window) -> Result<(), String> {
 59|     window.close().map_err(|e| e.to_string())
 60| }
 61| 
 62| #[tauri::command]
 63| async fn is_maximized(window: tauri::Window) -> Result<bool, String> {
 64|     window.is_maximized().map_err(|e| e.to_string())
 65| }
 66| 
 67| fn get_db_path() -> PathBuf {
 68|     let data_dir = dirs::data_local_dir()
 69|         .unwrap_or_else(|| PathBuf::from("."))
 70|         .join("hermes");
 71|     std::fs::create_dir_all(&data_dir).ok();
 72|     data_dir.join("providers.db")
 73| }
 74| 
 75| fn init_db(conn: &Connection) -> rusqlite::Result<()> {
 76|     conn.execute(
 77|         "CREATE TABLE IF NOT EXISTS providers (
 78|             id TEXT PRIMARY KEY,
 79|             type TEXT NOT NULL,
 80|             name TEXT NOT NULL,
 81|             api_key TEXT NOT NULL,
 82|             base_url TEXT,
 83|             model TEXT NOT NULL,
 84|             model_id TEXT,
 85|             active INTEGER DEFAULT 0,
 86|             is_default INTEGER DEFAULT 0
 87|         )",
 88|         [],
 89|     )?;
 90|     Ok(())
 91| }
 92| 
 93| /// Execute a Python script and return the result
 94| #[tauri::command]
 95| async fn execute_script(script_path: String, args: Vec<String>) -> Result<ScriptResult, String> {
 96|     let output = Command::new("python3")
 97|         .arg(&script_path)
 98|         .args(&args)
 99|         .output()
100|         .map_err(|e| format!("Failed to execute script: {}", e))?;
101| 
102|     let stdout = String::from_utf8_lossy(&output.stdout).to_string();
103|     let stderr = String::from_utf8_lossy(&output.stderr).to_string();
104| 
105|     Ok(ScriptResult {
106|         success: output.status.success(),
107|         output: stdout,
108|         error: if stderr.is_empty() { None } else { Some(stderr) },
109|     })
110| }
111| 
112| /// List all Python scripts in the scripts directory
113| #[tauri::command]
114| async fn list_scripts(app_handle: tauri::AppHandle) -> Result<Vec<String>, String> {
115|     let scripts_dir = app_handle
116|         .path()
117|         .app_data_dir()
118|         .map_err(|e| format!("Failed to get scripts dir: {}", e))?
119|         .join("scripts");
120| 
121|     // Create directory if it doesn't exist
122|     std::fs::create_dir_all(&scripts_dir)
123|         .map_err(|e| format!("Failed to create scripts dir: {}", e))?;
124| 
125|     let mut scripts = Vec::new();
126|     if let Ok(entries) = std::fs::read_dir(&scripts_dir) {
127|         for entry in entries.flatten() {
128|             if let Some(name) = entry.file_name().to_str() {
129|                 if name.ends_with(".py") {
130|                     scripts.push(name.to_string());
131|                 }
132|             }
133|         }
134|     }
135| 
136|     Ok(scripts)
137| }
138| 
139| /// Save/update a Python script
140| #[tauri::command]
141| async fn save_script(
142|     app_handle: tauri::AppHandle,
143|     name: String,
144|     content: String,
145| ) -> Result<String, String> {
146|     let scripts_dir = app_handle
147|         .path()
148|         .app_data_dir()
149|         .map_err(|e| format!("Failed to get scripts dir: {}", e))?
150|         .join("scripts");
151| 
152|     std::fs::create_dir_all(&scripts_dir)
153|         .map_err(|e| format!("Failed to create scripts dir: {}", e))?;
154| 
155|     let script_path = scripts_dir.join(&name);
156|     std::fs::write(&script_path, &content)
157|         .map_err(|e| format!("Failed to write script: {}", e))?;
158| 
159|     Ok(script_path.to_string_lossy().to_string())
160| }
161| 
162| /// Read a Python script content
163| #[tauri::command]
164| async fn read_script(app_handle: tauri::AppHandle, name: String) -> Result<String, String> {
165|     let script_path = app_handle
166|         .path()
167|         .app_data_dir()
168|         .map_err(|e| format!("Failed to get scripts dir: {}", e))?
169|         .join("scripts")
170|         .join(&name);
171| 
172|     std::fs::read_to_string(&script_path)
173|         .map_err(|e| format!("Failed to read script: {}", e))
174| }
