176| // ===== Provider CRUD Commands =====
177| 
178| #[tauri::command]
179| fn get_providers(state: tauri::State<AppState>) -> Result<Vec<LLMProvider>, String> {
180|     let conn = state.db.lock().map_err(|e| e.to_string())?;
181|     let mut stmt = conn
182|         .prepare("SELECT id, type, name, api_key, base_url, model, model_id, active, is_default FROM providers")
183|         .map_err(|e| e.to_string())?;
184| 
185|     let providers = stmt
186|         .query_map([], |row| {
187|             Ok(LLMProvider {
188|                 id: row.get(0)?,
189|                 provider_type: row.get(1)?,
190|                 name: row.get(2)?,
191|                 api_key: row.get(3)?,
192|                 base_url: row.get(4)?,
193|                 model: row.get(5)?,
194|                 model_id: row.get(6)?,
195|                 active: row.get::<_, i32>(7)? != 0,
196|                 is_default: row.get::<_, i32>(8)? != 0,
197|             })
198|         })
199|         .map_err(|e| e.to_string())?
200|         .filter_map(|r| r.ok())
201|         .collect();
202| 
203|     Ok(providers)
204| }
205| 
206| #[tauri::command]
207| fn save_provider(state: tauri::State<AppState>, provider: LLMProvider) -> Result<(), String> {
208|     let conn = state.db.lock().map_err(|e| e.to_string())?;
209|     
210|     // If this provider is being set as default, unset all others first
211|     if provider.is_default {
212|         conn.execute("UPDATE providers SET is_default = 0", [])
213|             .map_err(|e| e.to_string())?;
214|     }
215|     
216|     conn.execute(
217|         "INSERT OR REPLACE INTO providers (id, type, name, api_key, base_url, model, model_id, active, is_default)
218|          VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
219|         params![
220|             provider.id,
221|             provider.provider_type,
222|             provider.name,
223|             provider.api_key,
224|             provider.base_url,
225|             provider.model,
226|             provider.model_id,
227|             if provider.active { 1 } else { 0 },
228|             if provider.is_default { 1 } else { 0 }
229|         ],
230|     )
231|     .map_err(|e| e.to_string())?;
232| 
233|     Ok(())
234| }
235| 
236| #[tauri::command]
237| fn delete_provider(state: tauri::State<AppState>, id: String) -> Result<(), String> {
238|     let conn = state.db.lock().map_err(|e| e.to_string())?;
239|     conn.execute("DELETE FROM providers WHERE id = ?1", params![id])
240|         .map_err(|e| e.to_string())?;
241|     Ok(())
242| }
243| 
244| fn main() {
245|     // Initialize database
246|     let db_path = get_db_path();
247|     println!("Database path: {:?}", db_path);
248|     
249|     let conn = Connection::open(&db_path).expect("Failed to open database");
250|     init_db(&conn).expect("Failed to initialize database");
251|     
252|     let state = AppState {
253|         db: Mutex::new(conn),
254|     };
255| 
256|     tauri::Builder::default()
257|         .manage(state)
258|         .plugin(tauri_plugin_shell::init())
259|         .plugin(tauri_plugin_dialog::init())
260|         .invoke_handler(tauri::generate_handler![
261|             // Window controls
262|             minimize,
263|             toggle_maximize,
264|             close,
265|             is_maximized,
266|             // Scripts
267|             execute_script,
268|             list_scripts,
269|             save_script,
270|             read_script,
271|             // Providers
272|             get_providers,
273|             save_provider,
274|             delete_provider
275|         ])
276|         .run(tauri::generate_context!())
277|         .expect("error while running tauri application");
278| }

